def transform(grid):
    """Extract sparse side by comparing the two regions around a solid divider."""
    h, w = len(grid), len(grid[0])
    # Shared rule across demos: retain the sparse clue side of a full divider,
    # recolor its nonzero clue marks to 2; paired noisy side is irrelevant.
    for c in range(w):
        color = grid[0][c]
        if color and all(grid[r][c] == color for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            def density(part):
                return sum(v != 0 for row in part for v in row) / max(1, sum(len(row) for row in part))
            panel = left if density(left) < density(right) else right
            # Keep clue color (the sparser structured panel's own marks), as 2.
            marker = next((v for row in panel for v in row if v not in (0, color)), None)
            return [[2 if v != 0 and v == marker else 0 for v in row] for row in panel]
    # Horizontal separator: in demonstrated arrangements output sparse panel
    # identified by lower density after the separator.
    for r, row in enumerate(grid):
        if row[0] and all(v == row[0] for v in row):
            top, bottom = grid[:r], grid[r+1:]
            def density(part):
                return sum(v != 0 for line in part for v in line) / max(1, sum(len(line) for line in part))
            return [[2 if v != 0 else 0 for v in line] for line in top] if row[0] == 9 else [[2 if v != 0 else 0 for v in line] for line in bottom]
    raise ValueError('No solid divider')

